// The migration MANIFEST: the list of migrations this release was built to run against, compiled into the code (modules/config/expectedMigrations.ts) so the
// readiness probe can compare it with the database without reading the filesystem (a serverless host may not ship prisma/migrations at runtime).
// PURE. `npm run migrations:manifest` writes the file; a unit test fails when the committed file is stale, so a release cannot ship a stale manifest unnoticed.

export function renderManifest(names: readonly string[]): string {
  const sorted = [...names].sort();
  return [
    "// GENERATED by `npm run migrations:manifest` from prisma/migrations. Do not edit by hand: tests/unit/migrationManifest.test.ts fails when it is stale.",
    "// The readiness probe (app/api/ready) answers 'not ready' until the database has applied every migration listed here.",
    "export const EXPECTED_MIGRATIONS: readonly string[] = [",
    ...sorted.map((n) => `  ${JSON.stringify(n)},`),
    "];",
    "",
  ].join("\n");
}
